import{_ as t,o as a,c as i,a1 as o}from"./chunks/framework.DIevSSiF.js";const u=JSON.parse('{"title":"The Shadow Method","description":"","frontmatter":{},"headers":[],"relativePath":"reference/method.md","filePath":"reference/method.md"}'),n={name:"reference/method.md"};function s(r,e,h,c,d,l){return a(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="the-shadow-method" tabindex="-1">The Shadow Method <a class="header-anchor" href="#the-shadow-method" aria-label="Permalink to &quot;The Shadow Method&quot;">​</a></h1><p>Shadow repeats one bounded cycle: read the computer board, resume or claim one reachable checkpoint, do the work in its owning entity, reproduce its proof, then accept or return the claim. <a href="./grammar.html">The grammar</a> owns the exact plan, claim, proof, and lifecycle rules; this page owns the review step inside that cycle.</p><h2 id="attack-then-refute" tabindex="-1">Attack, then refute <a class="header-anchor" href="#attack-then-refute" aria-label="Permalink to &quot;Attack, then refute&quot;">​</a></h2><p>Before a checkpoint is accepted, attack the pinned change through every named review lens. An attack must state a concrete failure, counterexample, or smaller owner; vague concern is not a finding. Then try to refute each attack against fresh source and the smallest discriminating check.</p><ul><li>A refuted attack is recorded as no action. Do not manufacture a rewrite.</li><li>A surviving attack is fixed in the current checkpoint when it invalidates the contract. Otherwise it becomes one follow-up row with an exact wake or proof.</li><li>Re-run the checkpoint proof after the surviving fixes. Review output alone is never completion.</li></ul><p>The built-in lens set is:</p><ul><li><code>thermo</code> — attack duplicate ownership, branches, wrappers, and abstractions that can be deleted or folded into an existing boundary.</li><li><code>ponytail</code> — refute the proposed remedy, then choose <code>delete</code>, <code>reuse</code>, <code>keep</code>, or <code>defer</code> and state whether the technical mechanism works.</li></ul><p>A repository may declare a different bounded set without creating runtime state:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">adversarial-lenses</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">thermo, ponytail, taste</span></span></code></pre></div><p><code>shadow config --explain</code> prints the active set. These names are review perspectives for the native host. Shadow does not install them, route work to them, turn them into seats, or make a claim depend on their availability. A repository with no <code>shadow.yaml</code> uses the built-in set and remains fully functional.</p>`,10)])])}const m=t(n,[["render",s]]);export{u as __pageData,m as default};
